/*
 * Intact footer interactions, bound on existing footer markup (AEM footer component of the footer
 * Experience Fragment, injected by blocks/footer). Self-contained (no imports): also shipped in the
 * AEM clientlib (aem-intact clientlib-site js/footer.js, generated by tools/sync-from-eds.mjs).
 */

/** "Legal notes": disclosure of the legal notes panel */
function initNotes(footer) {
  const toggle = footer.querySelector('.footer-notes-toggle');
  const panel = toggle && footer.querySelector(`#${toggle.getAttribute('aria-controls')}`);
  if (!panel) return;
  toggle.addEventListener('click', () => {
    const open = toggle.getAttribute('aria-expanded') !== 'true';
    toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
    panel.hidden = !open;
  });
}

/**
 * @param {Element} footer the footer markup root (.footer-inner)
 */
export default function initFooter(footer) {
  if (!footer || footer.dataset.footerInit) return;
  footer.dataset.footerInit = 'true';
  initNotes(footer);
}
